// ─────────────────────────────────────────────────────────────────────────
//  01 · fallbacks for missing values★☆☆ core
//  concepts: null operators · IsNullOrWhiteSpace · int?
// ─────────────────────────────────────────────────────────────────────────
//
//  Missing data must stay visibly missing: never a crash, never a fake 0.

using static Bootcamp.Check;

string DisplayName(Customer? c)
{
    if (!string.IsNullOrWhiteSpace(c?.Nickname)) return c.Nickname.Trim();
    if (!string.IsNullOrWhiteSpace(c?.FullName)) return c.FullName.Trim();
    return "Guest";
}

int? ParseAge(string? input)
{
    if (string.IsNullOrWhiteSpace(input)) return null;
    return int.TryParse(input.Trim(), out var age) && age is >= 0 and <= 150 ? age : null;
}

// ──────────────────────────── tests ──────────────────────────────────────

Test("a nickname wins, trimmed", () =>
    Eq(DisplayName(new Customer(" Ana ", "Ana Lima")), "Ana"));

Test("a blank nickname falls back to the full name", () =>
    Eq(DisplayName(new Customer("   ", "Ana Lima")), "Ana Lima"));

Test("null customer or nothing usable gives Guest (boundary)", () =>
{
    Eq(DisplayName(null), "Guest");
    Eq(DisplayName(new Customer(null, " ")), "Guest");
});

Test("ParseAge reads whole numbers with whitespace", () =>
{
    Eq(ParseAge(" 42 "), (int?)42);
    Eq(ParseAge("0"), (int?)0);
});

Test("ParseAge rejects null, blank, junk and out-of-range values", () =>
{
    Ok(ParseAge(null) is null, "null");
    Ok(ParseAge("") is null, "empty");
    Ok(ParseAge("abc") is null, "abc");
    Ok(ParseAge("-1") is null, "-1");
    Ok(ParseAge("151") is null, "151");
});

// ──────────────────────────── types ──────────────────────────────────────

record Customer(string? Nickname, string? FullName);

fund-csharp/02-nullable-reference-types/.explanation:
`IsNullOrWhiteSpace` covers null, empty and blank in one call; after it returns false the compiler knows the value is not null:

```csharp
if (!string.IsNullOrWhiteSpace(c?.Nickname)) return c.Nickname.Trim();
if (!string.IsNullOrWhiteSpace(c?.FullName)) return c.FullName.Trim();
return "Guest";
```

`int.TryParse` never throws, and returning `int?` keeps "no age" distinct from "age 0". `c?.Nickname ?? c?.FullName ?? "Guest"` passes the null tests but fails the blank-nickname one.

